INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `Emote2`, `Emote3`, `Emote4`, `EmoteDelay1`, `EmoteDelay2`, `EmoteDelay3`, `EmoteDelay4`, `RewardText`, `VerifiedBuild`) VALUES
(40100, 0, 0, 0, 0, 0, 0, 0, 0, 'Ah, I assume you are the famous $N of whom I\'ve heard so much about, a pleasure to meet you. You can call me Vess.$B$BI understand that you need something from me, as it so happens, I also need something from you. So shall we talk business?', 0),
(40101, 0, 0, 0, 0, 0, 0, 0, 0, 'I will assume that you and Magellas didn\'t know what you got me into by sending me after those damned plates. I should have sent you to rob the royal treasury of Stormwind instead of giving you a menial task such as Bannor.$B$BBut a deal is a deal, and the Black Rose always holds up to her end of the bargain.', 0),
(40102, 0, 0, 0, 0, 0, 0, 0, 0, '<High Explorer Magellas reads the letter.>$B$BShave my beard and call me an elf, How in the world did she manage this? Ahm… I mean, this is more than good news, $N. We know the exact locations of the missing plates. And what is this mentioning of a cult?', 0),
(40172, 0, 0, 0, 0, 0, 0, 0, 0, 'I\'d like to say welcome aboard but ye are not ready to become a crew member yet, first ye must do us a favor.', 0),
(40173, 0, 0, 0, 0, 0, 0, 0, 0, 'Not so loud! You want the whole bruiser brigade on our hands? Just put that crate in and keep them coming.$B$B<After you bring each crate one by one you turn your attention towards Narkk.>$B$BFine work mate, here\'s your pay. Now leave and don\'t worry about it, you were never here today.', 0),
(40174, 0, 0, 0, 0, 0, 0, 0, 0, 'Aye, good job lad. This is all fer the greater good of the crew, aye?', 0),
(40175, 0, 0, 0, 0, 0, 0, 0, 0, 'Damn, look at this beauty, such a beautiful rock. Here, have some silver for the hard work of getting it for me. Some people should really learn not to flash their expensive rocks out in public, you never know who could be looking for them, heh.', 0),
(40178, 0, 0, 0, 0, 0, 0, 0, 0, 'What kind of monster am I to make ye sully such great rum, I hope one day I will be able to forgive meself.', 0),
(40179, 0, 0, 0, 0, 0, 0, 0, 0, 'The rat finally lays dead. Put that bag down fer now, I\'ll tell ye what ye gotta do next afore we get the deck all bloody.', 0),
(40180, 0, 0, 0, 0, 0, 0, 0, 0, 'Haha idiots! Now they know what\'s gonna happen when they try to mess with us next, great job. And welcome aboard.', 0),
(40182, 0, 0, 0, 0, 0, 0, 0, 0, 'So they be thar after all. Good, some of me scallywags be trackin\' behind ye to see if they can get any kind of information while ye be wreakin\' havoc, \'n it seems we got what we needs.', 0),
(40183, 0, 0, 0, 0, 0, 0, 0, 0, 'Aye, toss it on the floor over there, I\'ll be mountin\' it on me wall in the room I sleep.', 0),
(40185, 0, 0, 0, 0, 0, 0, 0, 0, 'I\'ll be damned, ye found something, eh? Looks like a damn normal compass to me.$B$B<Garfield frowns.>$B$BWhatever, we\'ll try it some other time.', 0),
(40186, 0, 0, 0, 0, 0, 0, 0, 0, 'Good, somethin\' else ye\'ve dealt with. I be startin\' to fear the thought of ye bein\' me enemy, mate.', 0),
(40187, 0, 0, 0, 0, 0, 0, 0, 0, 'Yo-ho-ho!', 0),
(40198, 0, 0, 0, 0, 0, 0, 0, 0, 'All this variety, you know what they say, variety is the spice of life! When we make our next journey this will all surely keep everyone in good spirits.$B$BLast time we ventured out, we barely had any ale left over, most of the barrels were destroyed, and let me tell you, Garfield would have my neck if anything like that ever happened again! Thanks for the hard work ye scurvy dog, take this money as a thanks.', 0),
(40222, 0, 0, 0, 0, 0, 0, 0, 0, 'Yeah, this is it, those pesky rats think they could stop me? Hah! Good work pal, you certainly got some gumption.', 0),
(40223, 0, 0, 0, 0, 0, 0, 0, 0, 'My my, see, I told you, there are always deals being made! Profits to be made, always of course, especially if you know how to come between it, heh! Here, take this coin, if you\'re interested in more work, I got it.', 0),
(40224, 0, 0, 0, 0, 0, 0, 0, 0, 'Let me guess, \'Slip\', huh? He always wanted to get the crew back together after we parted ways. I figured he\'d just slink away to some part of the world and live it out on the gold he made!', 0),
(40225, 0, 0, 0, 0, 0, 0, 0, 0, 'So, he did uphold his end of the bargain... Wally Wisecrack huh, that two faced piece of rat filth!$B$BI am going to get my revenge, and you\'re going to be the weapon I unleash upon this miserable prick.', 0),
(40226, 0, 0, 0, 0, 0, 0, 0, 0, 'It\'s done then, and good, the spirits of those that were lost because of this cold hearted goon may find peace in whatever grave they found themselves in. I can\'t thank you again for all the help, and for reconnecting me with some old crew across the world.$B$BTake one of these items, as a token of my gratitude.', 0),
(40327, 0, 0, 0, 0, 0, 0, 0, 0, 'Look at all this stuff! Spanners, Flaxpipes, Togwig Gears! This will last the Bloodsail quite a while, and give me a whole bunch of opportunity to tinker! Thanks again $N, this is a haul!', 0),
(40328, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, excellent, the less of them swimming about, the better for all of us. You\'ve done well, here, keep one, it might serve you well.', 0),
(40329, 0, 0, 0, 0, 0, 0, 0, 0, '<Willy would take his time inspecting the pelt for imperfections>. This might just be the one $N , nice job out there, this will certainly bring us some gold.$B$BHere, take your cut for the good work.', 0),
(40330, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh, McCoy sent you did he? Well, I can understand why, we\'ve hit some problems, and haven\'t been able to send out the goods that have been requested, perhaps you can help.', 0),
(40331, 0, 0, 0, 0, 0, 0, 0, 0, 'Heh, we\'ve butted heads with the Skullsplitter a few times, they should know not to mess around now. Nice job in getting back the booty.', 0),
(40332, 0, 0, 0, 0, 0, 0, 0, 0, 'Hey there, looking for anything specific?$B$BOh, that\'s why you\'re here huh, heh.', 0),
(40333, 0, 0, 0, 0, 0, 0, 0, 0, 'Welcome back, this is it huh?$B$BNot bad, nice work in getting it, now you know where we get some of our poisons, so keep it hush.', 0),
(40334, 0, 0, 0, 0, 0, 0, 0, 0, 'So, I take it everything is back in order huh? Well, from what I read you\'ve done a good job. You\'ve solved our supply issue, and for that you should be commended, take one of these items from the hoard, you\'ve earned it matey.', 0),
(40335, 0, 0, 0, 0, 0, 0, 0, 0, 'Monkeys, all of them, serve them right. Let me help you out with those!$B$BI hope you found some coins for your pockets because I\'m afraid I don\'t carry anything with me.', 0),
(40336, 0, 0, 0, 0, 0, 0, 0, 0, '<Jeesie\'s eyes sparkle at the treasure>.$B$BOh Cap\'n, it\'s beautiful, come put it on my neck, the sight will be the most treasured reward you\'d ever get!', 0),
(40337, 0, 0, 0, 0, 0, 0, 0, 0, 'Aye! Now let\'s try it.$B$BThis be strong and fine rum, here ye go Cap\'n yer share.', 0),
(40354, 0, 0, 0, 0, 0, 0, 0, 0, 'Hm, not something I would\'ve gone with. Alas, it be yer ship \'afore all.', 0),
(40355, 0, 0, 0, 0, 0, 0, 0, 0, 'This pleases me greatly, $N!$B$BYou\'ve begun your way towards my respect, thank you.', 0),
(40356, 0, 0, 0, 0, 0, 0, 0, 0, 'The language is unreadable to you and you bet it\'d be unreadable for the rest of your crewmates back at the retreat, it is by now you realize you should\'ve probably recruited a historian.', 0),
(40357, 0, 0, 0, 0, 0, 0, 0, 0, 'Told ya Vil\'do’s got a nose for dis things! But look at ya figurin\' out where to go and what we be huntin\'!', 0),
(40358, 0, 0, 0, 0, 0, 0, 0, 0, 'You stare at the huge statue and can\'t believe your eyes, it\'s made of pure gold! You dare question whether it\'s still there when you realize you will not be able to move it one inch.$B$BSeveral curses come out of your mind when you remember Vil\'do\'s words. Not only did you come this far, but you can\'t even grab them!', 0),
(40359, 0, 0, 0, 0, 0, 0, 0, 0, 'Okay bub, stand back while I assemble this thing, yeah?', 0),
(40360, 0, 0, 0, 0, 0, 0, 0, 0, 'As you push the button the shrink ray activates! Mumbling all sorts of sounds at first you start cursing the corpse of the goblin who built this, not only was he a double-crosser but he was no engineer! Or so you\'d think, sooner than later the statue began to shrink, no weighing less, and could easily be placed in your backpack.', 0),
(40361, 0, 0, 0, 0, 0, 0, 0, 0, 'Dis be great mon, very great, and ya be sayin\' ya can make dem big too? Ah dis be da greatest haul we got in a while now, great job mon, great job. Here be some coin for da troubles, I be takin\' dem statues and dat ray now.', 0),
(40362, 0, 0, 0, 0, 0, 0, 0, 0, 'And so you have it $N, or is it Captain $N? I guess I\'m a crewmate from now on, well, one only YOU can see.', 0),
(40970, 0, 0, 0, 0, 0, 0, 0, 0, 'Whoa there, pal! I gotta say, I didn\'t expect you to make it outta there in one piece. You\'re a real survivor, I\'ll give ya that! So, you\'re tellin\' me the mine\'s clear of them nasty basilisks? Well, ain\'t that splendid news! I\'ll have a mining team dispatched there pronto!$B$BNow, about that ore you managed to snag, I\'ll need ya to hand it over. Don\'t worry, I\'ll package it all up real nice and attach a fancy note for Todd. Long time no see, right? I\'m sure he\'ll be thrilled to get a package from me.', 0),
(41115, 0, 0, 0, 0, 0, 0, 0, 0, 'So, you got that coin?', 0),
(41329, 0, 0, 0, 0, 0, 0, 0, 0, 'Aw, was this the best ye could get?', 0),
(41330, 0, 0, 0, 0, 0, 0, 0, 0, 'That\'s the good stuff! The lads be already licking they lips.', 0),
(41331, 0, 0, 0, 0, 0, 0, 0, 0, 'Oho, now where\'d you get that? Something ye\'d toast at the table of the Pirate King! If there were one...', 0),
(41332, 0, 0, 0, 0, 0, 0, 0, 0, 'Shiver me timbers! The damned thing feels like the kiss of a Siren.', 0),
(55025, 0, 0, 0, 0, 0, 0, 0, 0, 'Ahh! It\'s been a dang while since I\'ve been able to drink! You\'ve surely saved us.', 0),
(60152, 0, 0, 0, 0, 0, 0, 0, 0, 'The Baron sent you? How kind of him to actually send reinforcements, come hear mate, lend me your ear, can\'t just say it out loud!', 0),
(60153, 0, 0, 0, 0, 0, 0, 0, 0, 'Good work, $N, I\'ll feed this to the crocodiles.$B$B<The Baron tosses the head into a bucket.>$B$BWhat\'s this?$B$BHe still has an eyepatch on, you can have it if you want, or I will give you this pearled necklace, you can only take one.$B$BThank you for your services, do stick around, you never know when I\'ll need more muscle.', 0),
(60155, 0, 0, 0, 0, 0, 0, 0, 0, 'Oh, wonderful legs! Grill \'em, boil \'em, put ‘em in a pot.$B$BYou... want a reward? I think this should be enough.', 0);
INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(40100, 0, 0, 'Yes?', 0),
(40101, 0, 0, 'You\'re still here? Don\'t tell me that you are scared of a few pirates.', 0),
(40102, 0, 0, '$N, I sure damn hope that you have good news for me because it appears that the Horde is on the move as well.', 0),
(40172, 0, 0, 'Don\'t waste me time mate, I be tryin\' to enjoy the sun and this here fine rum.', 0),
(40173, 0, 0, 'Aye?', 0),
(40174, 0, 0, 'Done already mate?', 0),
(40175, 0, 0, 'It might be hard to track him down, but I\'m sure you can do it.', 0),
(40178, 0, 0, 'Just go already, this action makes me eyes water.', 0),
(40179, 0, 0, 'Don\'t got all day.', 0),
(40180, 0, 0, 'Shiver me timbers, ye actually made it. Were they mad?', 0),
(40182, 0, 0, 'Still as weak as they used to be?', 0),
(40183, 0, 0, 'Bah, as ugly as it used to be.', 0),
(40185, 0, 0, 'How goes the search fer legends \'n myths?', 0),
(40186, 0, 0, 'Did it burn nicely?', 0),
(40187, 0, 0, 'It be no great honour mate, this ain\'t a knight\'s ceremony.', 0),
(40198, 0, 0, 'If you want to be a real smuggler , let me tell you, you need connections, and those connections need to be trustworthy.', 0),
(40222, 0, 0, 'Any luck? I can\'t be waiting around all day.', 0),
(40223, 0, 0, 'If you don\'t go looking around, you wont find a thing.', 0),
(40224, 0, 0, 'Howdy, what can I do for you?', 0),
(40225, 0, 0, 'Yes?', 0),
(40226, 0, 0, 'He is a dastardly fellow, don\'t let him know you\'re coming, or you\'ll never find him.', 0),
(40327, 0, 0, 'Make sure you keep yours eyes open out there!', 0),
(40328, 0, 0, 'The Naga can be a fearsome foe, battle hard, and put them down.', 0),
(40329, 0, 0, 'Any luck yet? Remember, it needs to be immaculate.', 0),
(40330, 0, 0, 'Yes?', 0),
(40331, 0, 0, 'Those trolls can be some mean sons of bitches, make sure you are cautious out there.', 0),
(40332, 0, 0, 'Yes?', 0),
(40333, 0, 0, 'Any news?', 0),
(40334, 0, 0, 'Any news?', 0),
(40335, 0, 0, 'Hurry Cap\'n, there be much to do.', 0),
(40336, 0, 0, 'Oh Cap\'n you\'re a tease and a half, quite the charmer I may say.', 0),
(40337, 0, 0, 'Can\'t wait to test it or taste it.', 0),
(40354, 0, 0, 'Any idea yet mate?', 0),
(40355, 0, 0, 'Is the fool dead?', 0),
(40356, 0, 0, 'The notes appear to be torn and dirty.', 0),
(40357, 0, 0, 'Got anythin\' boss mon?', 0),
(40358, 0, 0, 'Comparing the drawing from the journal it seems you\'re in the right place and this is the right statue.', 0),
(40359, 0, 0, 'Got them yet?', 0),
(40360, 0, 0, 'You stare at the statue with the engraved name once more and get ready to pull the trigger.', 0),
(40361, 0, 0, 'Aye boss mon, ya be back!', 0),
(40362, 0, 0, 'Am I dead?', 0),
(40970, 0, 0, 'Well, I told you already. You need to clear the mine.', 0),
(41115, 0, 0, '<He bites the gold coins one at a time, before storing them behind the counter. He says not one word more, but gives a terse nod and marks something down in his ledger.>', 0),
(41329, 0, 0, 'Ahoy, captain! Managed to sneak a peak over me new recipe, have ye? You know ale\'s closer to me heart and I am happy to provide to the rest of the lads anytime. And I believe so would ye. This takes us to the real problem, cap\'n.$B$BSee, the ale\'s fine but the lads be getting restless. It be too warm outside for us to drink just ale all day! And blasted be the Sea Witch if we\'d ever work sober. So as the captain of this crew, you must assume responsibility! Bah, me tongue be dancing around me mouth too much.$B$BWe need rum Cap\'n.', 0),
(41330, 0, 0, 'Ahoy, captain! Managed to sneak a peak over me new recipe, have ye? You know ale\'s closer to me heart and I am happy to provide to the rest of the lads anytime. And I believe so would ye. This takes us to the real problem, cap\'n.$B$BSee, the ale\'s fine but the lads be getting restless. It be too warm outside for us to drink just ale all day! And blasted be the Sea Witch if we\'d ever work sober. So as the captain of this crew, you must assume responsibility! Bah, me tongue be dancing around me mouth too much.$B$BWe need rum Cap\'n.', 0),
(41331, 0, 0, 'Ahoy, captain! Managed to sneak a peak over me new recipe, have ye? You know ale\'s closer to me heart and I am happy to provide to the rest of the lads anytime. And I believe so would ye. This takes us to the real problem, cap\'n.$B$BSee, the ale\'s fine but the lads be getting restless. It be too warm outside for us to drink just ale all day! And blasted be the Sea Witch if we\'d ever work sober. So as the captain of this crew, you must assume responsibility! Bah, me tongue be dancing around me mouth too much.$B$BWe need rum Cap\'n.', 0),
(41332, 0, 0, 'Ahoy, captain! Managed to sneak a peak over me new recipe, have ye? You know ale\'s closer to me heart and I am happy to provide to the rest of the lads anytime. And I believe so would ye. This takes us to the real problem, cap\'n.$B$BSee, the ale\'s fine but the lads be getting restless. It be too warm outside for us to drink just ale all day! And blasted be the Sea Witch if we\'d ever work sober. So as the captain of this crew, you must assume responsibility! Bah, me tongue be dancing around me mouth too much.$B$BWe need rum Cap\'n.', 0),
(55025, 0, 0, 'Get the booze yet? We\'re dying down here!', 0),
(60152, 0, 0, 'Rid me of these fools, my crew stands above all other.', 0),
(60153, 0, 0, 'Move it, or we both lose our lives!', 0),
(60155, 0, 14, 'Get a move on. My customers are waiting!', 0);
