INSERT INTO `areatable_dbc` (`ID`, `ContinentID`, `ParentAreaID`, `AreaBit`, `Flags`, `SoundProviderPref`, `SoundProviderPrefUnderwater`, `AmbienceID`, `ZoneMusic`, `IntroSound`, `ExplorationLevel`, `AreaName_Lang_enUS`, `AreaName_Lang_enGB`, `AreaName_Lang_koKR`, `AreaName_Lang_frFR`, `AreaName_Lang_deDE`, `AreaName_Lang_enCN`, `AreaName_Lang_zhCN`, `AreaName_Lang_enTW`, `AreaName_Lang_zhTW`, `AreaName_Lang_esES`, `AreaName_Lang_esMX`, `AreaName_Lang_ruRU`, `AreaName_Lang_ptPT`, `AreaName_Lang_ptBR`, `AreaName_Lang_itIT`, `AreaName_Lang_Unk`, `AreaName_Lang_Mask`, `FactionGroupMask`, `LiquidTypeID_1`, `LiquidTypeID_2`, `LiquidTypeID_3`, `LiquidTypeID_4`, `MinElevation`, `Ambient_Multiplier`, `Lightid`) VALUES
(5084, 0, 33, 3768, 1073741888, 0, 0, 0, 520, 0, 48, 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 'Bloodsail Retreat', 16712190, 0, 0, 0, 0, 0, -500.0, 0.0, 0);
INSERT INTO `creature_text` (`CreatureID`, `GroupID`, `ID`, `Text`, `Type`, `Language`, `Probability`, `Emote`, `Duration`, `Sound`, `BroadcastTextId`, `TextRange`, `comment`) VALUES
(60453, 0, 0, 'Well done, Cap\'n!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66662'),
(60453, 1, 0, 'Set yer veils high \'n conquer this world under yer name \'n the Jolly Roger o\' the Bloodsail Buccaneers!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66663'),
(60453, 2, 0, 'Ahoy! Now let\'s get some rum \'n party.', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66426'),
(60453, 3, 0, 'Yo-ho-ho!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66427'),
(60453, 4, 0, 'The Crying Dandelion, eh? Didn\'t take ye for a romantic. So be it, the vessel\'s name will be so from now on, I will let the crew know.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66404'),
(60496, 0, 0, 'Well done, Cap\'n!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66662'),
(60496, 1, 0, 'Set yer veils high \'n conquer this world under yer name \'n the Jolly Roger o\' the Bloodsail Buccaneers!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66663'),
(60496, 2, 0, 'Ahoy! Now let\'s get some rum \'n party.', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66426'),
(60496, 3, 0, 'Yo-ho-ho!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66427'),
(60496, 4, 0, 'The Crying Dandelion, eh? Didn\'t take ye for a romantic. So be it, the vessel\'s name will be so from now on, I will let the crew know.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66404'),
(2496, 100, 0, 'You dare? You\'re not getting out of here alive, bub!', 14, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66117'),
(2496, 101, 0, 'You\'re telling me there\'s a beach party?! I get the feelin\' that if I\'m being invited this is no small get-together. Normally I\'d say I\'m too busy but I\'m sensing an opportunity here - rest, relaxation, and revenue! I\'ll be there for sure, ya can bet on that.', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66116'),
(60643, 0, 0, 'Yeah, I don\'t think so bub!', 12, 0, 0, 0, 0, 0, 0, 0, 'Turtle broadcast text 66714');
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9060496, 'Ahoy matey, I am very curious to see what new chapter for the Bloodsail Buccaneers you will be painting. I will be watching the Cap\'n\'s lodge for a while but when ye come here to rest or spend some alone time I will be gone.', 'Ahoy matey, I am very curious to see what new chapter for the Bloodsail Buccaneers you will be painting. I will be watching the Cap\'n\'s lodge for a while but when ye come here to rest or spend some alone time I will be gone.', 1, 0);
