INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030015, 'Oh boss mon, ya can\'t take da whole crew with ya, da rest got stuff of dey own to do and da ship be not ready to sail yet. Ya gonna have to do dis da hard way.', 'Oh boss mon, ya can\'t take da whole crew with ya, da rest got stuff of dey own to do and da ship be not ready to sail yet. Ya gonna have to do dis da hard way.', 1, 0);
