INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9030016, 'It seems death claimed me $r, I am Sovatir, Arcanist and Lorekeeper of Eldre\'thalas, I have placed a part of my soul and memories in that journal, when you spoke the incantation you brought it up. I should let you know that it ate at your life force however, not too much I trust.\n\nSince you\'re now the owner of the journal, you\'re also mine, my knowledge is yours as long as you keep me entertained and allow me to find even more. Do note, that nobody else can see me.', 'It seems death claimed me $r, I am Sovatir, Arcanist and Lorekeeper of Eldre\'thalas, I have placed a part of my soul and memories in that journal, when you spoke the incantation you brought it up. I should let you know that it ate at your life force however, not too much I trust.\n\nSince you\'re now the owner of the journal, you\'re also mine, my knowledge is yours as long as you keep me entertained and allow me to find even more. Do note, that nobody else can see me.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9030016, 9030016);
INSERT INTO `npc_text` (`ID`, `text0_0`, `text0_1`, `Probability0`, `VerifiedBuild`) VALUES (9060644, 'I bear the knowledge of the Shen\'dralar, I am a Highborne of Eldre\'thalas and I know a great deal about our world. Since you can aid me to gain even more knowledge I am at your service, Captain.', 'I bear the knowledge of the Shen\'dralar, I am a Highborne of Eldre\'thalas and I know a great deal about our world. Since you can aid me to gain even more knowledge I am at your service, Captain.', 1, 0);
INSERT INTO `gossip_menu` (`MenuID`, `TextID`) VALUES (9060644, 9060644);
